import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Button,
  Box,
  Chip,
  IconButton,
} from "@mui/material";

import ArrowBackIcon from "@mui/icons-material/ArrowBack";

import { useEffect, useState } from "react";

import {
  Link,
  useNavigate,
} from "react-router-dom";

import API from "../services/api";

export default function MyBlogs() {

  const [blogs, setBlogs] = useState([]);

  const navigate = useNavigate();

  const user = JSON.parse(
    localStorage.getItem("user")
  );

  useEffect(() => {

    const fetchBlogs = async () => {

      try {

        const response = await API.get(
          `/blogs?author=${user._id}`
        );

        setBlogs(response.data);

      } catch (error) {

        console.log(error);
      }
    };

    fetchBlogs();

  }, [user._id]);

  return (

    <Container
      maxWidth="xl"
      sx={{
        py: 6,
        minHeight: "100vh",
      }}
    >
{/* PREMIUM HEADER */}

<Box
  sx={{
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    mb: 6,
    flexWrap: "wrap",
    gap: 3,
  }}
>

  {/* LEFT SECTION */}

  <Box
    sx={{
      display: "flex",
      alignItems: "center",
      gap: 2,
      position:"relative",
    }}
  >

    <IconButton
      onClick={() => navigate("/")}
      sx={{
  position: "fixed",

  top: {
    xs: 18,
    sm: 24,
  },

  left: {
    xs: 16,
    sm: 24,
  },

  width: {
    xs: 48,
    sm: 54,
  },

  height: {
    xs: 48,
    sm: 54,
  },

  background:
    "linear-gradient(90deg,  #020617 0%,  #08112b 35%,  #172554 100%)",

  color: "white",

  boxShadow: "0 8px 25px rgba(99,102,241,0.35)",

  zIndex: 1000,

  "&:hover": {
    transform: "scale(1.08)",
    background:
      "linear-gradient(90deg,  #101118 0%,  #191a1f 35%,  #1725541c 100%)",
  },

  transition: "0.3s",
}}
    >
      <ArrowBackIcon />
    </IconButton>

    <Box>

      <Typography
        variant="h3"
        fontWeight={800}
        sx={{
          background:
            "linear-gradient(90deg,  #020617 0%,  #08112b 35%,  #172554 100%)",
          WebkitBackgroundClip: "text",
          WebkitTextFillColor: "transparent",
        }}
      >
        My Blogs
      </Typography>

      <Typography
        variant="body1"
        color="text.secondary"
      >
        Manage your published blogs
      </Typography>

    </Box>

  </Box>

  {/* RIGHT SIDE */}

  <Button
    variant="contained"
    onClick={() => navigate("/create-blog")}
    sx={{
  position: "fixed",

  top: {
    xs: 18,
    sm: 24,
  },

  right: {
    xs: 16,
    sm: 24,
  },

  width: {
    xs: 150,
    sm: 150,
  },

  height: {
    xs: 48,
    sm: 54,
  },

  background:
    "linear-gradient(90deg,  #020617 0%,  #08112b 35%,  #172554 100%)",

  color: "white",

  boxShadow: "0 8px 25px rgba(99,102,241,0.35)",

  zIndex: 1000,

  "&:hover": {
    transform: "scale(1.08)",
    background:
      "linear-gradient(90deg,  #02061711 0%,  #08112b 35%,  #172554 100%)",
  },

  transition: "0.3s",
}}
  >
    + Create Blog
  </Button>

</Box>
      

      {/* EMPTY STATE */}

      {blogs.length === 0 && (

        <Box
          sx={{
            textAlign: "center",
            mt: 10,
          }}
        >

          <Typography
            variant="h5"
            fontWeight={700}
            gutterBottom
          >
            No blogs yet
          </Typography>

          <Typography
            color="text.secondary"
          >
            Start creating amazing blogs 🚀
          </Typography>

        </Box>
      )}

      {/* BLOG GRID */}

      <Grid container spacing={4}>

        {blogs.map((blog) => (

          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={blog._id}
          >

            <Card
              sx={{
                height: "100%",
                borderRadius: 5,
                overflow: "hidden",
                boxShadow: 3,
                transition: "0.3s",

                "&:hover": {
                  transform: "translateY(-8px)",
                  boxShadow: 8,
                },
              }}
            >

              <CardMedia
                component="img"
                height="220"
                image={
                  blog.image ||
                  "https://images.unsplash.com/photo-1499750310107-5fef28a66643"
                }
                alt={blog.title}
              />

              <CardContent
                sx={{
                  p: 3,
                }}
              >

                <Chip
                  label={
                    blog.category || "General"
                  }
                  color="primary"
                  sx={{ mb: 2 }}
                />

                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{ mb: 1 }}
                >
                  By {user.name}
                </Typography>

                <Typography
                  variant="h5"
                  fontWeight={700}
                  gutterBottom
                >
                  {blog.title}
                </Typography>

                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{
                    mb: 3,
                    minHeight: 60,
                  }}
                >
                  {blog.content?.slice(0, 80)}...
                </Typography>

                <Button
                  component={Link}
                  to={`/blog/${blog._id}`}
                  variant="contained"
                  fullWidth
                  sx={{
                    py: 1.3,
                    borderRadius: 3,
                    fontWeight: 700,
                    textTransform: "none",
                    fontSize: "1rem",
                  }}
                >
                  Read More
                </Button>

              </CardContent>

            </Card>

          </Grid>
        ))}

      </Grid>

    </Container>
  );
}
